import{_ as a,c as e,a2 as d,o as n}from"./chunks/framework.BnrAgU0Y.js";const s="/bllm/assets/1fa0344baa3642fadbdbc89567cccc9b.BsFsga2x.png",o="/bllm/assets/3d351c564fef6af96845bd620863240b.BYUGEXGL.png",m=JSON.parse('{"title":"Langflow中的逻辑组件","description":"Langflow中的逻辑组件","frontmatter":{"title":"Langflow中的逻辑组件","description":"Langflow中的逻辑组件","layout":"doc"},"headers":[],"relativePath":"langflow/components-logic.md","filePath":"langflow/components-logic.md"}'),r={name:"langflow/components-logic.md"};function l(i,t,h,p,c,u){return n(),e("div",null,t[0]||(t[0]=[d('<h1 id="langflow中的逻辑组件" tabindex="-1">Langflow中的逻辑组件 <a class="header-anchor" href="#langflow中的逻辑组件" aria-label="Permalink to &quot;Langflow中的逻辑组件&quot;">​</a></h1><p>逻辑组件为路由、条件处理和流管理提供功能。</p><h2 id="在流程中使用逻辑组件" tabindex="-1">在流程中使用逻辑组件 <a class="header-anchor" href="#在流程中使用逻辑组件" aria-label="Permalink to &quot;在流程中使用逻辑组件&quot;">​</a></h2><p>此流程使用 <a href="/bllm/components-logic.html#loop">循环 (Loop)</a> 组件创建一个汇总的 &quot;for each&quot; 循环。</p><p>该组件遍历 <a href="/bllm/concepts-objects.html#data-object">数据 (Data)</a> 对象的列表，直到完成，然后 <strong>完成 (Done)</strong> 循环汇总结果。</p><p><strong>文件 (File)</strong> 组件从本地计算机加载文本文件，然后 <strong>解析数据 (Parse Data)</strong> 组件将其解析为结构化的 <code>数据 (Data)</code> 对象列表。 <strong>循环 (Loop)</strong> 组件将每个 <code>数据 (Data)</code> 对象传递给一个 <strong>提示 (Prompt)</strong> 进行汇总。</p><p>当 <strong>循环 (Loop)</strong> 组件没有 <code>数据 (Data)</code> 时，<strong>完成 (Done)</strong> 循环激活，它通过另一个 <strong>提示 (Prompt)</strong> 计算页数并汇总其语气。 在 Langflow 中，这通过将解析数据组件的 <strong>数据列表 (Data List)</strong> 输出连接到循环组件的 <code>数据 (Data)</code> 循环输入来表示。</p><p><img src="'+s+`" alt="Sample Flow looping summarizer"></p><p>输出将会类似如下：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>_&lt;!-- --&gt;10    Document Summary</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    Total Pages Processed</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    Total Pages: 2</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    Overall Tone of Document</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    Tone: Informative and Instructional</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    The documentation outlines microservices architecture patterns and best practices. </span></span>
<span class="line"><span>_&lt;!-- --&gt;10    It emphasizes service isolation and inter-service communication protocols.</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    The use of asynchronous messaging patterns is recommended for system scalability.</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    It includes code examples of REST and gRPC implementations to demonstrate integration approaches.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>翻译如下：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>_&lt;!-- --&gt;10    文档摘要</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    处理的总页数</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    总页数：2</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    文档整体语气</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    语气：信息性和指导性</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    文档概述了微服务架构模式和最佳实践。</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    强调了服务隔离和服务间的通信协议。</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    推荐使用异步消息传递模式以提高系统的可扩展性。</span></span>
<span class="line"><span>_&lt;!-- --&gt;10    包含 REST 和 gRPC 实现的代码示例以展示集成方法。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>注意：微服务 (microservices)、REST 和 gRPC 等术语在技术文档中通常保持原样。</p><h2 id="条件路由器-if-else-组件" tabindex="-1">条件路由器（If-Else 组件） <a class="header-anchor" href="#条件路由器-if-else-组件" aria-label="Permalink to &quot;条件路由器（If-Else 组件）&quot;">​</a></h2><p><a href="#conditional-router-if-else-component">​</a></p><p>该组件根据文本比较将输入消息路由到相应的输出。</p><p>ConditionalRouterComponent（条件路由器组件）基于文本比较路由消息。它通过使用指定的运算符比较两个文本输入来评估条件，并相应地路由消息。</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>input_text</td><td>String</td><td>操作的主要文本输入。</td></tr><tr><td>match_text</td><td>String</td><td>需要进行比较的文本输入。</td></tr><tr><td>operator</td><td>Dropdown</td><td>用于比较文本的运算符。</td></tr><tr><td>case_sensitive</td><td>Boolean</td><td>如果为真，则比较时区分大小写。</td></tr><tr><td>message</td><td>Message</td><td>要通过任一路径传递的消息。</td></tr><tr><td>max_iterations</td><td>Integer</td><td>条件路由器的最大迭代次数。</td></tr><tr><td>default_route</td><td>Dropdown</td><td>达到最大迭代次数时采用的默认路径。</td></tr></tbody></table><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>true_result</td><td>Message</td><td>条件为真时的输出。</td></tr><tr><td>false_result</td><td>Message</td><td>条件为假时的输出。</td></tr></tbody></table><h2 id="data条件路由器" tabindex="-1">Data条件路由器 <a class="header-anchor" href="#data条件路由器" aria-label="Permalink to &quot;Data条件路由器&quot;">​</a></h2><p>该组件基于指定键的条件（包括布尔验证）路由<code>Data</code>对象。</p><p>此组件在需要对复杂数据结构进行条件路由的工作流中特别有用，使得能够基于数据内容进行动态决策。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>data_input</td><td>Data</td><td>要处理的数据对象或数据对象列表。</td></tr><tr><td>key_name</td><td>String</td><td>要检查的数据对象中键的名称。</td></tr><tr><td>operator</td><td>Dropdown</td><td>用于比较值的运算符。</td></tr><tr><td>compare_value</td><td>String</td><td>要比较的值（不用于布尔验证器）。</td></tr></tbody></table><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>true_output</td><td>数据/列表</td><td>条件满足时的输出。</td></tr><tr><td>false_output</td><td>数据/列表</td><td>条件不满足时的输出。</td></tr></tbody></table><h2 id="flow-作为工具" tabindex="-1">Flow 作为工具 <a class="header-anchor" href="#flow-作为工具" aria-label="Permalink to &quot;Flow 作为工具&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>此组件自 Langflow 版本 1.1.2 起不推荐使用。 请使用 <a href="/bllm/components-logic.html#run-flow">运行 Flow 组件</a>。</p></div><p>该组件从一个运行已加载 Flow 的函数构建一个工具。</p><h3 id="inputs-1" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-1" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>flow_name</td><td>Dropdown</td><td>要运行的流程名称。</td></tr><tr><td>tool_name</td><td>String</td><td>工具的名称。</td></tr><tr><td>tool_description</td><td>String</td><td>工具的描述。</td></tr><tr><td>return_direct</td><td>Boolean</td><td>如果为 true，直接从工具返回结果。</td></tr></tbody></table><h3 id="输出-1" tabindex="-1">输出 <a class="header-anchor" href="#输出-1" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>api_build_tool</td><td>Tool</td><td>从流程构建而成的工具。</td></tr></tbody></table><h2 id="listen" tabindex="-1">Listen <a class="header-anchor" href="#listen" aria-label="Permalink to &quot;Listen&quot;">​</a></h2><p>此组件监听通知并检索其相关状态。</p><h3 id="inputs-2" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-2" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>要监听的通知的名称。</td></tr></tbody></table><h3 id="输出-2" tabindex="-1">输出 <a class="header-anchor" href="#输出-2" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>output</td><td>Data</td><td>与通知关联的状态。</td></tr></tbody></table><h2 id="loop" tabindex="-1">Loop <a class="header-anchor" href="#loop" aria-label="Permalink to &quot;Loop&quot;">​</a></h2><p>该组件遍历一个 <a href="https://example.com/concepts-objects#data-object" target="_blank" rel="noreferrer">数据</a> 对象列表，每次输出一个项目，并从循环输入中汇总结果。</p><h3 id="inputs-3" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-3" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>data</td><td>数据/列表</td><td>要迭代的初始数据对象列表。</td></tr></tbody></table><h3 id="outputs-1" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-1" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>item</td><td>数据</td><td>一次从数据列表中输出一项。</td></tr><tr><td>done</td><td>数据</td><td>迭代完成时触发，返回聚合结果。</td></tr></tbody></table><h2 id="notify" tabindex="-1">Notify <a class="header-anchor" href="#notify" aria-label="Permalink to &quot;Notify&quot;">​</a></h2><p>此组件生成一个通知供 Listen 组件使用。</p><h3 id="inputs-4" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-4" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>通知的名称。</td></tr><tr><td>data</td><td>Data</td><td>要存储在通知中的数据。</td></tr><tr><td>append</td><td>Boolean</td><td>如果为 true，记录将附加到已有的通知。</td></tr></tbody></table><h3 id="outputs-2" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-2" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>output</td><td>Data</td><td>存储在通知中的数据。</td></tr></tbody></table><h2 id="传递消息" tabindex="-1">传递消息 <a class="header-anchor" href="#传递消息" aria-label="Permalink to &quot;传递消息&quot;">​</a></h2><p>该组件会不改变地转发输入消息。</p><h3 id="inputs-5" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-5" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>input_message</td><td>Input Message</td><td>将要传递的信息。</td></tr><tr><td>ignored_message</td><td>Ignored Message</td><td>第二条将被忽略的信息。用于连续性的权宜之计。</td></tr></tbody></table><h3 id="outputs-3" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-3" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>output_message</td><td>Output Message</td><td>转发的输入信息。</td></tr></tbody></table><h2 id="运行流程" tabindex="-1">运行流程 <a class="header-anchor" href="#运行流程" aria-label="Permalink to &quot;运行流程&quot;">​</a></h2><p>该组件允许您在不打开流程编辑器的情况下运行存储在您Langflow数据库中的任何流程。</p><p>当连接到一个<a href="./URL.html">Agent</a>时，运行流程组件也可以作为一个工具使用。Agent用来注册工具的<code>name</code>和<code>description</code>元数据会被自动创建。</p><p>当您选择一个流程时，组件会获取该流程的图结构，并使用它来生成运行流程组件的输入和输出。</p><p>要将运行流程组件用作工具，请执行以下操作：</p><p><img src="`+o+'" alt="Run Flow component"></p><h3 id="inputs-6" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-6" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>flow_name_selected</td><td>Dropdown</td><td>要运行的流程名称。</td></tr><tr><td>flow_tweak_data</td><td>Dict</td><td>自定义流程行为的调整字典。</td></tr><tr><td>dynamic inputs</td><td>Various</td><td>根据选定的流程生成的附加输入。</td></tr></tbody></table><h3 id="outputs-4" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-4" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>run_outputs</td><td>类型为 <code>Data</code>、<code>Message</code> 或 <code>DataFrame</code> 的 <code>List</code>（列表）</td><td>所有输出均由执行流程生成。</td></tr></tbody></table><h2 id="sub-flow" tabindex="-1">Sub flow <a class="header-anchor" href="#sub-flow" aria-label="Permalink to &quot;Sub flow&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>important 本组件自 Langflow 版本 1.1.2 起<strong>已被弃用</strong>。建议使用<a href="./components-logic.html#run-flow">运行流程组件</a>。</p></div><p><code>SubFlowComponent</code> 组件生成一个包含流程所有输入输出的组件。</p><p>这个组件可以将整个流程集成为更大工作流中的一个组件。它会根据所选的流程动态生成输入，并使用提供的参数执行流程。</p><h3 id="输入-1" tabindex="-1">输入 <a class="header-anchor" href="#输入-1" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>flow_name</td><td>Dropdown</td><td>要运行的流程名称。</td></tr></tbody></table><h3 id="输出-3" tabindex="-1">输出 <a class="header-anchor" href="#输出-3" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>flow_outputs</td><td>List[Data]</td><td>从流中生成的输出。</td></tr></tbody></table>',77)]))}const g=a(r,[["render",l]]);export{m as __pageData,g as default};
